export async function execute(args = {}) {
  const rows = [...(args.rows || [])].sort((a, b) => Number(a[args.key]) - Number(b[args.key]))
  return { rows }
}

import test from 'node:test'
import assert from 'node:assert'
import { execute } from '../lib/impl.js'
test('sort', async () => {
  const r = await execute({ key: 'n', rows: [{ n: 3 }, { n: 1 }, { n: 2 }] })
  assert.deepEqual(r.rows.map((x) => x.n), [1, 2, 3])
})
